parts.css:
.trail-row { box-sizing: border-box; width: 100%; min-height: 64px; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: var(--space-gap-related) var(--space-gap-group); align-items: center; padding: var(--card-padding, var(--space-inset)); border: 1px solid var(--color-outline); border-radius: var(--card-radius, var(--radius-container)); background: var(--card-bg, var(--color-surface-raised)); color: var(--color-on-surface); font: inherit; text-align: start; cursor: pointer; }
.trail-row:hover { background: color-mix(in srgb, var(--card-bg, var(--color-surface-raised)) 92%, var(--color-on-surface)); }
.trail-row:active { background: color-mix(in srgb, var(--card-bg, var(--color-surface-raised)) 84%, var(--color-on-surface)); }
.trail-row:focus-visible { outline: var(--focus-width) solid var(--color-focus-ring); outline-offset: var(--focus-offset); }
.trail-name { font-family: var(--type-title-font-family); font-size: var(--type-body-font-size); font-weight: var(--type-title-font-weight); }
.trail-meta { grid-column: 1; color: var(--color-on-surface-variant); }
.trail-row .tag { grid-column: 2; grid-row: 1 / span 2; }

.tag { display: inline-flex; align-items: center; padding: 0 var(--space-inset-tight); border: 1px solid transparent; border-radius: var(--radius-pill); background: var(--color-primary-container); color: var(--color-on-primary-container); }
.tag[data-level="hard"] { background: transparent; border-color: var(--color-on-surface); color: var(--color-on-surface); }
.tag[data-level="hard"]::before { content: "▲" / ""; margin-inline-end: var(--space-gap-related); }

.btn { min-height: 48px; max-width: 100%; padding: var(--space-inset-tight) var(--button-padding-x, var(--space-inset)); border: 0; border-radius: var(--button-radius, var(--radius-control)); background: var(--button-primary-bg, var(--color-primary)); color: var(--button-primary-fg, var(--color-on-primary)); cursor: pointer; }
.btn:hover { background: color-mix(in srgb, var(--button-primary-bg, var(--color-primary)) 92%, var(--color-on-surface)); }
.btn:active { background: color-mix(in srgb, var(--button-primary-bg, var(--color-primary)) 80%, var(--color-on-surface)); }
.btn:focus-visible { outline: var(--focus-width) solid var(--color-focus-ring); outline-offset: var(--focus-offset); }
.btn:disabled { background: color-mix(in srgb, var(--color-on-surface) 12%, transparent); color: color-mix(in srgb, var(--color-on-surface) 50%, transparent); cursor: not-allowed; }

.fld { display: grid; gap: var(--space-gap-related); }
.fld-input { box-sizing: border-box; width: 100%; min-height: 48px; padding: 0 var(--space-inset); border: 1px solid var(--color-outline); border-radius: var(--radius-control); background: var(--color-surface); color: var(--color-on-surface); font: inherit; }
.fld-input:focus-visible { outline: var(--focus-width) solid var(--color-focus-ring); outline-offset: 0; border-color: var(--color-focus-ring); }
.fld-input:disabled { border-style: dashed; color: var(--color-on-surface-variant); }
.fld-input[aria-invalid="true"] { border: 2px solid var(--color-error); }
.fld-error { color: var(--color-error); }
